sql.if:
WITH RECURSIVE category_tree AS ( SELECT id FROM categories WHERE id = #{request.categoryId}
UNION ALL
SELECT c.id FROM categories c INNER JOIN category_tree ct ON c.parent_id = ct.id )

mapper.select:


SELECT COUNT(*)
FROM (
    SELECT p.id
    FROM products p
    INNER JOIN product_variants pv
    ON pv.product_id = p.id
    WHERE p.status = 'ACTIVE'

     AND LOWER(p.name) LIKE CONCAT('%', LOWER(#{request.keyword}), '%') 

        AND p.category_id IN (
            SELECT id
            FROM category_tree
        )

     AND p.shop_id = #{request.shopId} 
     AND p.rating >= #{request.minRating} 

    GROUP BY p.id


        HAVING 1 = 1
         AND MIN(pv.price) >= #{request.minPrice} 
         AND MIN(pv.price) <= #{request.maxPrice} 


) result
